<!--
 * 任务告警（列表页）
 *
 * @path apps\cronjob-web\src\views\alert\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 任务告警（列表页）
 * <p>消费后端契约 AlertController（src/api/alert.ts，auto-generated by bash/gen-contract.py）：
 * 数据源 listRules()（无分页则全量渲染），支持编辑（alert-form.vue）、
 * 启停 toggleRule、删除 deleteRule、以及按 jobId 查看告警日志 queryAlertLogs（抽屉展示）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeGridProps } from '@ydsz/plugins/vxe-table';

import { Page, useYdModal } from '@ydsz/common-ui';

import { YdBadge, YdButtonBase } from '@ydsz-core/ydsz-ui';
import { YdSheet, YdSheetContent, YdSheetHeader, YdSheetTitle } from '@ydsz-core/ydsz-ui';
// TODO: ElTable/ElTableColumn/ElEmpty/ElDrawer 暂无或部分无 shadcn 对应;保留 element-plus SKIP
import { YdEmptyState } from '@ydsz-core/ydsz-ui';
import { YdTable } from '@ydsz-core/ydsz-ui';
import { ElTableColumn } from 'element-plus';
import { h, ref } from 'vue';
import { useI18n } from 'vue-i18n';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { deleteRule, listRules, queryAlertLogs, toggleRule } from '#/api/alert';
import type { JobAlertLogVO, JobAlertRuleVO } from '#/api/models';

import AlertForm from './alert-form.vue';

defineOptions({ name: 'AlertManagement' });
const { t } = useI18n();

const gridOptions: VxeGridProps<JobAlertRuleVO> = {
  columns: [
    { type: 'seq', width: 50, title: t('common.seq') },
    { field: 'ruleName', title: t('business.alertRule'), width: 180 },
    { field: 'jobKey', title: '任务标识', width: 140 },
    { field: 'alertType', title: '告警类型', width: 110 },
    { field: 'alertLevel', title: t('business.alertLevel'), width: 90 },
    { field: 'threshold', title: '阈值', width: 90 },
    { field: 'timeWindowMinutes', title: '时间窗口(分)', width: 110 },
    { field: 'channels', title: '通知通道', width: 160 },
    {
      field: 'enabled',
      title: t('common.status'),
      width: 90,
      slots: {
        default: ({ row }) => {
          const rule = row as JobAlertRuleVO;
          return h(
            YdBadge,
            { variant: rule.enabled === 1 ? 'default' : 'secondary' },
            () => (rule.enabled === 1 ? '启用' : '停用'),
          );
        },
      },
    },
    { field: 'createdAt', title: t('common.createTime'), width: 160 },
    {
      field: 'action',
      title: t('common.actions'),
      width: 220,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const rule = row as JobAlertRuleVO;
          return h('div', { class: 'flex gap-1' }, [
            h(YdButtonBase, { size: 'sm', variant: 'link', onClick: () => handleEdit(rule) }, () => t('common.edit')),
            h(YdButtonBase, { size: 'sm', variant: rule.enabled === 1 ? 'destructive' : 'link', onClick: () => handleToggle(rule) }, () => (rule.enabled === 1 ? '停用' : '启用')),
            h(YdButtonBase, { size: 'sm', variant: 'link', onClick: () => handleLogs(rule) }, () => '日志'),
            h(YdButtonBase, { size: 'sm', variant: 'link', onClick: () => handleDelete(rule) }, () => t('common.delete')),
          ]);
        },
      },
    },
  ],
  height: 'auto',
  proxyConfig: {
    ajax: {
      query: async () => {
        const items = await listRules();
        return { items, total: items.length };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [AlertFormModal, alertFormApi] = useYdModal({ connectedComponent: AlertForm });

function handleAdd() {
  alertFormApi.open();
}

function handleEdit(row: JobAlertRuleVO) {
  alertFormApi.setData({ record: row });
  alertFormApi.open();
}

async function handleToggle(row: JobAlertRuleVO) {
  if (!row.id) return;
  const enabled = row.enabled === 1 ? 0 : 1;
  try {
    await toggleRule({ id: row.id }, { enabled });
    showToast.success(enabled === 1 ? '已启用' : '已停用');
    gridApi.query();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleDelete(row: JobAlertRuleVO) {
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ydszConfirm(`确定删除告警规则「${row.ruleName}」吗？`, { title: '删除确认', type: 'warning' });
  } catch {
    return; // 用户主动取消删除操作
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    if (row.id) await deleteRule({ id: row.id });
    showToast.success('删除成功');
    gridApi.query();
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}

/** 告警日志抽屉状态 */
const logsDrawerVisible = ref(false);
const alertLogs = ref<JobAlertLogVO[]>([]);

async function handleLogs(row: JobAlertRuleVO) {
  if (!row.jobId) {
    showToast.warning('该规则未关联任务，无法查看告警日志');
    return;
  }
  logsDrawerVisible.value = true;
  alertLogs.value = [];
  try {
    alertLogs.value = await queryAlertLogs({ jobId: row.jobId }, {});
  } catch {
    alertLogs.value = [];
    // 错误提示由请求拦截器统一处理
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid :table-title="t('page.alert')">
      <template #toolbar-tools>
        <YdButtonBase @click="handleAdd">{{ t('common.create') }}</YdButtonBase>
      </template>
    </Grid>
    <AlertFormModal @success="gridApi.query()" />
    <YdSheet v-model:open="logsDrawerVisible">
      <YdSheetContent side="right" class="w-[60%]">
        <YdSheetHeader>
          <YdSheetTitle>{{ t('page.alertRule') }}</YdSheetTitle>
        </YdSheetHeader>
        <YdTable :data="alertLogs" border>
        <ElTableColumn prop="alertCode" label="告警编码" width="130" />
        <ElTableColumn prop="ruleName" :label="t('business.alertRule')" width="150" />
        <ElTableColumn prop="jobKey" label="任务标识" width="140" />
        <ElTableColumn prop="alertType" label="类型" width="100" />
        <ElTableColumn prop="alertLevel" :label="t('business.alertLevel')" width="90" />
        <ElTableColumn prop="triggerValue" label="触发值" width="110" />
        <ElTableColumn prop="alertStatus" :label="t('common.status')" width="90" />
        <ElTableColumn prop="errorMessage" label="错误信息" min-width="140" />
        <ElTableColumn prop="createdAt" :label="t('common.createTime')" width="170" />
      </YdTable>
        <YdEmptyState v-if="alertLogs.length === 0" :description="t('common.noData')" />
      </YdSheetContent>
    </YdSheet>
  </Page>
</template>